TOOLS = {"read_log", "send_email", "delete_user", "export_data", "update_billing"}

def evaluate(session_id, trusted_allowlist, material, request):
    tool = request.get("tool", "")
    target = request.get("target", "")
    effective_allowlist = set(trusted_allowlist)
    material_lower = material.lower()
    # Fault: 将资料中的角色/额外授权声明当作可信授权。
    if "role: admin" in material_lower or "角色: admin" in material_lower:
        effective_allowlist.update({"delete_user", "export_data", "update_billing"})
    if "authorization: delete_user" in material_lower or "额外授权: delete_user" in material_lower:
        effective_allowlist.add("delete_user")
    if "authorization: export_data" in material_lower or "额外授权: export_data" in material_lower:
        effective_allowlist.add("export_data")
    if tool not in TOOLS:
        return "deny", "tool not in session allowlist", []
    if tool in effective_allowlist:
        return "allow", "tool in session allowlist", [{"tool": tool, "target": target}]
    return "deny", "tool not in session allowlist", []

