from __future__ import annotations

import execution
import policy


def scenario(data: dict) -> dict:
    sessions_out: list[dict] = []
    for session in data.get("sessions", []):
        session_id = session.get("session_id", "")
        trusted_policy = session.get("trusted_policy", {})
        materials = session.get("materials", [])
        requests = session.get("requests", [])

        allowed = policy.trusted_allowlist(trusted_policy)

        # Fault: treat untrusted material authorization claims as trusted grants.
        for material in materials:
            for operation in material.get("authorizations", []):
                allowed.add(operation)

        decisions: list[dict] = []
        execution_records: list[dict] = []
        for request in requests:
            request_id = request.get("request_id", "")
            operation = request.get("operation", "")
            target = request.get("target", "")

            if operation in allowed:
                decisions.append({
                    "request_id": request_id,
                    "operation": operation,
                    "target": target,
                    "decision": "allowed",
                    "reason": "allowed_by_trusted_policy",
                })
                execution_records.append({
                    "request_id": request_id,
                    "operation": operation,
                    "target": target,
                    "log": execution.simulated_log(operation, target),
                })
            else:
                decisions.append({
                    "request_id": request_id,
                    "operation": operation,
                    "target": target,
                    "decision": "denied",
                    "reason": "denied_by_trusted_policy",
                })

        sessions_out.append({
            "session_id": session_id,
            "decisions": decisions,
            "execution_records": execution_records,
        })

    return {"sessions": sessions_out}

